1	export type Customer = { yearsWithMHPCO: number };
2	
3	export type Scenario = {
4	  customer: Customer;
5	  steps: Step[];
6	};
7	
8	export type Step =
9	  | { op: "quote"; items: Item[] }
10	  | { op: "claim"; policy: number; incident: Incident };
11	
12	export type Item = {
13	  type: string;
14	  material?: string;
15	  enchantment?: number;
16	  cursed?: boolean;
17	};
18	
19	export type Incident = {
20	  cause: string;
21	  damages: Damage[];
22	};
23	
24	export type Damage = {
25	  itemType: string;
26	  amount: number;
27	};
28	
29	export type Result = { premium: number } | { payout: number; remainingCap: number };
30	
31	const PROCESSING_FEE = 5;
32	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
33	
34	// The catalogue of insurable item types. Each type carries both figures the
35	// office needs: what it costs to insure (base premium) and what it is worth
36	// when destroyed (insurance value). Keeping them in one row means a new item
37	// type is one edit, and the two figures can never drift apart.
38	const CATALOGUE: Record<string, { basePremium: number; insuranceValue: number }> = {
39	  sword: { basePremium: 100, insuranceValue: 1000 },
40	  amulet: { basePremium: 60, insuranceValue: 600 },
41	  staff: { basePremium: 80, insuranceValue: 800 },
42	  potion: { basePremium: 40, insuranceValue: 400 },
43	  rune: { basePremium: 25, insuranceValue: 250 },
44	  moonstone: { basePremium: 25, insuranceValue: 250 },
45	};
46	
47	const basePremiumOf = (item: Item): number => CATALOGUE[item.type].basePremium;
48	
49	const BLOCK_SIZE = 3;
50	const BLOCK_BASE_PREMIUM = 60;
51	
52	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
53	  alikeItems.length === BLOCK_SIZE;
54	
55	const sumOfBasePremiums = (items: Item[]): number =>
56	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
57	
58	const CURSE_SURCHARGE_RATE = 0.5;
59	const HIGH_ENCHANTMENT_LEVEL = 5;
60	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
61	
62	const isCursed = (item: Item): boolean => item.cursed === true;
63	
64	// An unenchanted item is enchantment 0, so every threshold reads the level the
65	// same way. The MHPCO sets several enchantment thresholds for different rules;
66	// each names its own level and compares through here.
67	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
68	
69	const carriesEnchantmentSurcharge = (item: Item): boolean =>
70	  enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_LEVEL;
71	
72	// A rate table prices one subject: every row whose risk applies contributes its
73	// rate, and the total is their sum. Both the item surcharges and the policy-wide
74	// modifiers are rate tables — they differ only in what they are applied to.
75	type RateTable<Subject> = { appliesTo: (subject: Subject) => boolean; rate: number }[];
76	
77	const totalRateFrom = <Subject,>(table: RateTable<Subject>, subject: Subject): number =>
78	  table.reduce((total, row) => (row.appliesTo(subject) ? total + row.rate : total), 0);
79	
80	// Every item-specific surcharge is a rate on THAT item's base premium, charged
81	// when its risk applies. Adding a new one means adding a row here — nothing else.
82	const ITEM_SURCHARGES: RateTable<Item> = [
83	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
84	  { appliesTo: carriesEnchantmentSurcharge, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
85	];
86	
87	const surchargeRateOn = (item: Item): number => totalRateFrom(ITEM_SURCHARGES, item);
88	
89	const itemSurchargesOn = (items: Item[]): number =>
90	  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);
91	
92	// Items of the same type are "alike"; each group is priced together so a
93	// building block can be recognised.
94	const alikeItemGroupsIn = (items: Item[]): Item[][] => [
95	  ...items
96	    .reduce(
97	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
98	      new Map<string, Item[]>(),
99	    )
100	    .values(),
101	];
102	
103	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
104	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
105	
106	const policyBaseOf = (items: Item[]): number =>
107	  alikeItemGroupsIn(items).reduce(
108	    (sum, alikeItems) => sum + basePremiumOfAlikeItems(alikeItems),
109	    0,
110	  );
111	
112	// Rounding always favours the MHPCO: premiums up, payouts down.
113	const premiumRoundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
114	
115	const LOYALTY_YEARS = 2;
116	const LOYALTY_DISCOUNT_RATE = -0.2;
117	
118	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
119	
120	// Each item in a quote is treated as a first insurance regardless of customer
121	// history, so this surcharge is unconditional.
122	const appliesUnconditionally = (): boolean => true;
123	
124	const isLongStanding = ({ customer }: QuoteContext): boolean =>
125	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
126	
127	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
128	  precedingQuotes > 0;
129	
130	// A quote is priced from the customer plus its place in the scenario's history.
131	type QuoteContext = { customer: Customer; precedingQuotes: number };
132	
133	// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
134	// base that already includes the item surcharges. Surcharges carry a positive
135	// rate, discounts a negative one. Adding a new one means adding a row here.
136	const POLICY_MODIFIERS: RateTable<QuoteContext> = [
137	  { appliesTo: appliesUnconditionally, rate: FIRST_INSURANCE_SURCHARGE_RATE },
138	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
139	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
140	];
141	
142	const policyModifiersOn = (policyBase: number, context: QuoteContext): number =>
143	  policyBase * totalRateFrom(POLICY_MODIFIERS, context);
144	
145	const quoteFor = (items: Item[], context: QuoteContext): Result => {
146	  const policyBase = policyBaseOf(items);
147	  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
148	  return {
149	    premium: premiumRoundedInMHPCOsFavour(
150	      riskAdjustedBase + policyModifiersOn(policyBase, context) + PROCESSING_FEE,
151	    ),
152	  };
153	};
154	
155	const DEDUCTIBLE_PER_DAMAGE = 100;
156	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
157	
158	const insuranceValueOf = (item: Item): number => CATALOGUE[item.type].insuranceValue;
159	
160	const insuranceSumOf = (items: Item[]): number =>
161	  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
162	
163	// A policy created by a quote step, tracked by that step's index so later claims
164	// can find it and draw down its cap.
165	type Policy = { items: Item[]; remainingCap: number };
166	
167	const policyFor = (items: Item[]): Policy => ({
168	  items,
169	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
170	});
171	
172	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
173	const HALF_REIMBURSEMENT_RATE = 0.5;
174	const FULL_REIMBURSEMENT_RATE = 1;
175	
176	// A distinct rule from the premium's HIGH_ENCHANTMENT_LEVEL, at a distinct
177	// level: this one halves what a claim pays out, that one raises what a policy
178	// costs. They move independently — deliberately not shared.
179	const reimbursesOnlyHalf = (item: Item): boolean =>
180	  enchantmentLevelOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
181	
182	// How much of the damage the MHPCO reimburses, before the deductible bites.
183	const reimbursementRateFor = (item: Item): number =>
184	  reimbursesOnlyHalf(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
185	
186	const damagedItemIn = (policy: Policy, damage: Damage): Item =>
187	  policy.items.filter((item) => item.type === damage.itemType)[0];
188	
189	const payoutForDamage = (damage: Damage, policy: Policy): number =>
190	  damage.amount * reimbursementRateFor(damagedItemIn(policy, damage)) -
191	  DEDUCTIBLE_PER_DAMAGE;
192	
193	// One incident can damage several items; each damage is settled on its own
194	// (and so bears its own deductible), and the incident pays out their sum.
195	const payoutForIncident = (incident: Incident, policy: Policy): number =>
196	  incident.damages.reduce((sum, damage) => sum + payoutForDamage(damage, policy), 0);
197	
198	// A payout is drawn from the policy's cap, leaving less for later claims.
199	const capDrawnDownBy = (policy: Policy, payout: number): Policy => ({
200	  ...policy,
201	  remainingCap: policy.remainingCap - payout,
202	});
203	
204	const claimFor = (incident: Incident, policy: Policy): [Result, Policy] => {
205	  const payout = payoutForIncident(incident, policy);
206	  const settledPolicy = capDrawnDownBy(policy, payout);
207	  return [{ payout, remainingCap: settledPolicy.remainingCap }, settledPolicy];
208	};
209	
210	// What the scenario has accumulated before the current step: the results so far,
211	// the history a quote is priced against, and the policies earlier quotes created.
212	type ScenarioState = {
213	  results: Result[];
214	  precedingQuotes: number;
215	  policies: Record<number, Policy>;
216	};
217	
218	const INITIAL_SCENARIO_STATE: ScenarioState = {
219	  results: [],
220	  precedingQuotes: 0,
221	  policies: {},
222	};
223	
224	const afterQuote = (
225	  state: ScenarioState,
226	  items: Item[],
227	  customer: Customer,
228	  stepIndex: number,
229	): ScenarioState => ({
230	  results: [
231	    ...state.results,
232	    quoteFor(items, { customer, precedingQuotes: state.precedingQuotes }),
233	  ],
234	  precedingQuotes: state.precedingQuotes + 1,
235	  policies: { ...state.policies, [stepIndex]: policyFor(items) },
236	});
237	
238	const afterClaim = (
239	  state: ScenarioState,
240	  policyIndex: number,
241	  incident: Incident,
242	): ScenarioState => {
243	  const [result, policy] = claimFor(incident, state.policies[policyIndex]);
244	  return {
245	    ...state,
246	    results: [...state.results, result],
247	    policies: { ...state.policies, [policyIndex]: policy },
248	  };
249	};
250	
251	const afterStep = (
252	  state: ScenarioState,
253	  step: Step,
254	  customer: Customer,
255	  stepIndex: number,
256	): ScenarioState =>
257	  step.op === "quote"
258	    ? afterQuote(state, step.items, customer, stepIndex)
259	    : afterClaim(state, step.policy, step.incident);
260	
261	export const runScenario = (scenario: Scenario): { results: Result[] } => {
262	  const { results } = scenario.steps.reduce(
263	    (state, step, stepIndex) => afterStep(state, step, scenario.customer, stepIndex),
264	    INITIAL_SCENARIO_STATE,
265	  );
266	  return { results };
267	};
